// https://silken-muskox-24e.notion.site/Pharos-Delegation-Documentation-3078ec314f7580319e13d4b623e59548
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.0;

interface IStaking {
    struct Validator {
        string description;
        string publicKey;
        string publicKeyPop;
        string blsPublicKey;
        string blsPublicKeyPop;
        string endpoint;
        uint8 status;
        bytes32 poolId;
        uint256 totalStake;
        address owner;
        uint256 stakeSnapshot;
        uint256 pendingWithdrawStake;
        uint8 pendingWithdrawWindow;
    }

    struct PendingUndelegation {
        address delegator;
        bytes32 poolId;
        uint256 amount;
        uint256 unlockEpoch;
        uint256 pendingWithdrawWindow;
        bool processed;
        uint256 principalAmount; // Amount backed by real contract balance
        uint256 rewardAmount; // Amount that needs to be minted by client
    }

    struct Delegator {
        uint256 principalStake; // Tracks actual deposits (excluding compounded rewards)
        uint256 stake;
        uint256 accumulatedRewardPerShare;
        uint256 rewards;
        uint256 pendingStake;
        uint256 pendingWithdrawStake;
        uint256 pendingWithdrawWindow;
        uint256 totalRewardsClaimed;
        bool isPendingUndelegate;
    }

    /**
     * @notice Emitted when a delegator stakes tokens to a validator's pool
     * @param delegator Address of the delegator who initiated the stake
     * @param poolId Unique identifier of the validator's pool
     * @param amount Amount of tokens delegated
     * @param effectiveEpoch Epoch number when the delegation becomes effective
     * @dev The event uses indexed parameters for efficient filtering by delegator and poolId
     */
    event StakeDelegated(address indexed delegator, bytes32 indexed poolId, uint256 amount, uint256 effectiveEpoch);

    /**
     * @notice Emitted when a delegator initiates an undelegation from a validator's pool
     * @param delegator Address of the delegator who initiated the undelegation
     * @param poolId Unique identifier of the validator's pool
     * @param amount Total amount to withdraw (stake + unclaimed rewards)
     * @param unlockEpoch Epoch number when the undelegated funds become withdrawable
     * @dev The event uses indexed parameters for efficient filtering by delegator and poolId
     */
    event StakeUndelegated(address indexed delegator, bytes32 indexed poolId, uint256 amount, uint256 unlockEpoch);

    /**
     * @notice Emitted when a delegator claims their accumulated rewards from a validator's pool
     * @param delegator Address of the delegator who claimed rewards
     * @param poolId Unique identifier of the validator's pool
     * @param amount Amount of rewards claimed
     * @dev The event uses indexed parameters for efficient filtering by delegator and poolId
     */
    event RewardClaimed(address indexed delegator, bytes32 indexed poolId, uint256 amount);

    /**
     * @notice Emitted when a validator's commission rate is updated
     * @param poolId Unique identifier of the validator's pool
     * @param oldRate Previous commission rate (scaled by 10000, e.g., 1000 = 10%)
     * @param newRate New commission rate (scaled by 10000, e.g., 1500 = 15%)
     * @dev The event uses indexed parameter for efficient filtering by poolId
     */
    event CommissionRateChanged(bytes32 indexed poolId, uint256 oldRate, uint256 newRate);

    /**
     * @notice Emitted when a delegator compounds their unclaimed rewards into additional stake
     * @param delegator Address of the delegator who compounded rewards
     * @param poolId Unique identifier of the validator's pool
     * @param amount Amount of rewards compounded into stake
     * @dev The event uses indexed parameters for efficient filtering by delegator and poolId
     */
    event RewardsCompounded(address indexed delegator, bytes32 indexed poolId, uint256 amount);

    /**
     * @notice Emitted when new coins are minted (for rewards) and credited to a beneficiary
     * @param beneficiary Address of the account receiving the minted coins
     * @param reason Code indicating the reason for minting (1: delegator rewards, 2: validator commissions, etc.)
     * @param amount Amount of coins minted
     * @dev The event uses indexed parameters for efficient filtering by beneficiary and reason
     */
    event CoinMinted(address indexed beneficiary, uint8 indexed reason, uint256 amount);

    // ==================== Validator Interfaces ====================

    function isValidatorActive(bytes32 _poolId) external view returns (bool);
    function isValidatorPendingAdd(bytes32 _poolId) external view returns (bool);
    function isValidatorPendingUpdate(bytes32 _poolId) external view returns (bool);
    function isValidatorPendingExit(bytes32 _poolId) external view returns (bool);
    function registerValidator(
        string memory _description,
        string memory _publicKey,
        string memory _publicKeyPop,
        string memory _blsPublicKey,
        string memory _blsPublicKeyPop,
        string memory _endpoint
    ) external payable returns (bytes32);
    function updateValidator(bytes32 _poolId, string memory _description, string memory _endpoint) external;
    function updateValidatorOwner(bytes32 _poolId, address _newOwner) external;
    function exitValidator(bytes32 _poolId) external;
    function addStake(bytes32 _poolId) external payable;
    function advanceEpoch() external;
    function advanceEpoch(bytes32[] memory _poolIds, uint256[] memory _priorityFees) external;
    function getActiveValidators() external view returns (bytes32[] memory);
    function getPendingAddValidators() external view returns (bytes32[] memory);
    function getPendingExitValidators() external view returns (bytes32[] memory);
    function getPendingUpdateValidators() external view returns (bytes32[] memory);
    function slashValidator(bytes32 _poolId) external;
    function withdrawStake(bytes32 _poolId, uint256 _withdrawStake) external;
    function claimStake(bytes32 _poolId) external;
    function getImplAddress() external view returns (address);
    function updateImplAddress(address _newImplementationAddress) external;

    // ==================== Delegation Interfaces ====================

    /**
     * @notice Delegates tokens to a validator's pool (for external delegators)
     * @param _poolId Unique identifier of the validator's pool
     * @dev The function is payable (msg.value is the amount of tokens to delegate)
     * @dev Requires the validator to have delegation enabled and the delegator to be in the whitelist (if enabled)
     * @dev The delegation takes effect at the next epoch
     * emit StakeDelegated Event with delegator address, poolId, amount, and effective epoch
     */
    function delegate(bytes32 _poolId) external payable;

    /**
     * @notice Initiates full undelegation from a validator's pool (withdraws stake + rewards)
     * @param _poolId Unique identifier of the validator's pool
     * @return amount Total amount to withdraw (stake + unclaimed rewards)
     * @return unlockEpoch Epoch number when the funds become withdrawable
     * @dev Only the delegator can call this function for their own stake
     * @dev Does not support partial undelegation (full stake only)
     * @dev Adds the delegator to the pending undelegation queue
     * emit StakeUndelegated Event with delegator address, poolId, amount, and unlock epoch
     */
    function undelegate(bytes32 _poolId) external returns (uint256 amount, uint256 unlockEpoch);

    /**
     * @notice Claims unclaimed rewards from a validator's pool for the caller
     * @param _poolId Unique identifier of the validator's pool
     * @return amount Amount of rewards claimed (and minted to the delegator)
     * @dev Only the delegator can claim their own rewards
     * @dev Triggers CoinMinted event for reward distribution (platform-side minting)
     * emit RewardClaimed Event with delegator address, poolId, and claimed amount
     * emit CoinMinted Event with delegator address, reason code (1 for delegator rewards), and amount
     */
    function claimReward(bytes32 _poolId) external returns (uint256);

    /**
     * @notice Compounds unclaimed rewards into additional stake in a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @dev Only the delegator can compound their own rewards
     * @dev Converts unclaimed rewards into additional delegated stake
     * emit RewardsCompounded Event with delegator address, poolId, and compounded amount
     */
    function compoundRewards(bytes32 _poolId) external;

    /**
     * @notice Settles (calculates) unclaimed rewards for the caller from a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @dev Updates the delegator's unclaimed rewards balance (lazy accounting)
     * @dev No events emitted (purely a state update for the delegator)
     */
    function settleReward(bytes32 _poolId) external;

    /**
     * @notice Updates the commission rate for a validator's pool (fee taken from delegator rewards)
     * @param _poolId Unique identifier of the validator's pool
     * @param _newRate New commission rate (scaled by 10000, e.g., 1000 = 10%, 10000 = 100%)
     * @dev Only the validator owner can call this function
     * @dev The new rate cannot exceed 100% (10000 in scaled value)
     * emit CommissionRateChanged Event with poolId, old rate, and new rate
     */
    function setCommissionRate(bytes32 _poolId, uint256 _newRate) external;

    /**
     * @notice Enables or disables delegation for a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @param _enabled Boolean indicating if delegation should be enabled (true) or disabled (false)
     * @dev Only the validator owner can call this function
     * @dev Disabling delegation prevents new delegations but does not affect existing ones
     */
    function setDelegationEnabled(bytes32 _poolId, bool _enabled) external;

    /**
     * @notice Adds a delegator to the validator's whitelist (if whitelist is enabled)
     * @param _poolId Unique identifier of the validator's pool
     * @param _delegator Address of the delegator to add to the whitelist
     * @dev Only the validator owner can call this function
     * @dev Whitelisted delegators can delegate even if the pool has restricted delegation
     */
    function addDelegatorToWhitelist(bytes32 _poolId, address _delegator) external;

    /**
     * @notice Removes a delegator from the validator's whitelist (if whitelist is enabled)
     * @param _poolId Unique identifier of the validator's pool
     * @param _delegator Address of the delegator to remove from the whitelist
     * @dev Only the validator owner can call this function
     * @dev Does not affect existing delegations from the removed address
     */
    function removeDelegatorFromWhitelist(bytes32 _poolId, address _delegator) external;

    /**
     * @notice Returns detailed information about a delegator's stake in a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @param _delegator Address of the delegator to query
     */
    function getDelegator(bytes32 _poolId, address _delegator) external view returns (Delegator memory delegator);

    /**
     * @notice Calculates the current unclaimed rewards for a delegator in a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @param _delegator Address of the delegator to query
     * @return Amount of unclaimed rewards (including both settled and unsettled rewards)
     * @dev Uses lazy accounting to calculate rewards based on current reward-per-share
     */
    function getDelegatorReward(bytes32 _poolId, address _delegator) external view returns (uint256);

    /**
     * @notice Returns the current commission rate for a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @return Current commission rate (scaled by 10000, e.g., 1000 = 10%, 10000 = 100%)
     */
    function getCommissionRate(bytes32 _poolId) external view returns (uint256);

    /**
     * @notice Returns the total number of active validators
     * @return count Number of active validators
     */
    function getActiveValidatorCount() external view returns (uint256);

    /**
     * @notice Returns the total number of delegators across all active validator pools
     * @return count Total number of delegators
     */
    function getTotalDelegatorCount() external view returns (uint256);

    // ==================== Extended Query Interfaces ====================

    /**
     * @notice Returns detailed information about a validator
     * @param _poolId Unique identifier of the validator's pool
     * @return validator Validator struct containing all validator details
     */
    function getValidator(bytes32 _poolId) external view returns (Validator memory validator);

    /**
     * @notice Returns all validator pool IDs (active and inactive)
     * @return poolIds Array of all validator pool IDs
     */
    function getAllValidators() external view returns (bytes32[] memory poolIds);

    /**
     * @notice Returns the count of validators by status
     * @return activeCount Number of active validators
     * @return inactiveCount Number of inactive validators (pending add but not yet active)
     * @return pendingExitCount Number of validators pending exit
     */
    function getValidatorCounts()
        external
        view
        returns (uint256 activeCount, uint256 inactiveCount, uint256 pendingExitCount);

    /**
     * @notice Returns the current blockchain information
     * @return currentEpoch Current epoch number
     * @return currentBlock Current block height
     * @return totalStake Total staked across all validators
     */
    function getBlockchainInfo() external view returns (uint256 currentEpoch, uint256 currentBlock, uint256 totalStake);

    /**
     * @notice Returns user's total staking information across all validators
     * @param _delegator Address of the delegator to query
     * @return totalStake Total amount of PROS staked across all validators
     * @return totalRewards Total unclaimed rewards across all validators
     * @return totalClaimed Total rewards already claimed across all validators
     */
    function getUserTotalInfo(address _delegator)
        external
        view
        returns (uint256 totalStake, uint256 totalRewards, uint256 totalClaimed);

    /**
     * @notice Returns list of validators where the user has staked
     * @param _delegator Address of the delegator to query
     * @return poolIds Array of pool IDs where the user has stakes
     * @return stakes Array of stake amounts corresponding to each pool ID
     * @return rewards Array of unclaimed rewards corresponding to each pool ID
     */
    function getUserValidators(address _delegator)
        external
        view
        returns (bytes32[] memory poolIds, uint256[] memory stakes, uint256[] memory rewards);

    /**
     * @notice Returns all pending undelegations for a user
     * @param _delegator Address of the delegator to query
     * @return undelegations Array of PendingUndelegation structs
     */
    function getUserPendingUndelegations(address _delegator)
        external
        view
        returns (PendingUndelegation[] memory undelegations);

    /**
     * @notice Returns the estimated APR for a validator's pool
     * @param _poolId Unique identifier of the validator's pool
     * @return apr Estimated annual percentage rate (scaled by 100, e.g., 500 = 5%)
     * @dev APR is calculated based on inflation rate and validator's share of total stake
     */
    function getValidatorApr(bytes32 _poolId) external view returns (uint256 apr);
}

contracts/pharos/SlpPharosProxy.sol.content:
/////////////////////////////////////////////////////////////////////////////////
//   ____   _____  ______  _____    ____    _____  _______     _____   ____    //
//  |  _ \ |_   _||  ____||  __ \  / __ \  / ____||__   __|   |_   _| / __ \   //
//  | |_) |  | |  | |__   | |__) || |  | || (___     | |        | |  | |  | |  //
//  |  _ <   | |  |  __|  |  _  / | |  | | \___ \    | |        | |  | |  | |  //
//  | |_) | _| |_ | |     | | \ \ | |__| | ____) |   | |    _  _| |_ | |__| |  //
//  |____/ |_____||_|     |_|  \_\ \____/ |_____/    |_|   (_)|_____| \____/   //
//                                                                             //
/////////////////////////////////////////////////////////////////////////////////
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.28;

import {IStaking} from "../interfaces/pharos/IStaking.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {
    AccessControlEnumerableUpgradeable
} from "@openzeppelin/contracts-upgradeable/access/extensions/AccessControlEnumerableUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/// @title SlpPharosProxy
/// @notice A contract that manages Pharos's bonding, unbonding, claiming, and transferring back assets
///         for whitelisted poolIds using a specified collateral token and a Hyperbridge handler.
/// @author Bifrost Team
contract SlpPharosProxy is AccessControlEnumerableUpgradeable, ReentrancyGuardUpgradeable {
    using EnumerableSet for EnumerableSet.Bytes32Set;

    /// @notice Storage structure for the SlpPharosProxy contract.
    struct SlpPharosProxyStorage {
        /// @notice Set of whitelisted validator pool Ids.
        EnumerableSet.Bytes32Set _poolIds;
        /// @notice Address of the bridge vault contract.
        address _bridgeVault;
        /// @notice Address of the rewards vault contract.
        address _rewardsVault;
        /// @notice Total amount bonded.
        uint256 _totalBonded;
        /// @notice Total amount unbonded.
        uint256 _totalUnbonded;
        /// @notice Total amount of rewards claimed from Pharos via claimReward / batchClaimReward.
        uint256 _totalRewardClaimed;
        /// @notice Total amount transferred to the rewards vault via transferToRewardsVault.
        uint256 _totalRewardTransferred;
    }

    /// @notice Pharos Staking contract address.
    IStaking public constant STAKING = IStaking(0x4100000000000000000000000000000000000000);

    // keccak256(abi.encode(uint256(keccak256("bifrost.storage.SlpPharosProxy")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant _STORAGE_LOCATION = 0xa0268512d1ad72d0bd2136fed798eeda2422eb8b727c15d33589fbbf5c9a8d00;

    /// @notice Returns the storage location for SlpPharosProxy.
    /// @return $ The storage location for SlpPharosProxy.
    function getSlpPharosProxyStorage() private pure returns (SlpPharosProxyStorage storage $) {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := _STORAGE_LOCATION
        }
    }

    /// @notice The role required to perform actions in this contract.
    bytes32 public constant WHITELIST_ROLE = keccak256("WHITELIST_ROLE");

    /// @notice Emitted when a pool id is whitelisted.
    /// @param sender The address that whitelisted the pool id.
    /// @param poolId The address of the whitelisted validator.
    event PoolIdRegistered(address indexed sender, bytes32 indexed poolId);
    /// @notice Emitted when a validator is removed from the whitelist.
    /// @param sender The address that removed the validator.
    /// @param poolId The address of the removed validator.
    event PoolIdUnRegistered(address indexed sender, bytes32 indexed poolId);
    /// @notice Emitted when collateral is bonded to a validator.
    /// @param sender The address that bonded the collateral.
    /// @param poolId The pool id of the validator to which collateral was bonded.
    /// @param amount The amount of collateral deposited.
    event Bonded(address indexed sender, bytes32 indexed poolId, uint256 amount);
    /// @notice Emitted when collateral is unbonded from a validator.
    /// @param sender The address that unbonded the collateral.
    /// @param poolId The pool id of the validator to which collateral was bonded.
    /// @param amount Total amount to withdraw (stake + unclaimed rewards).
    /// @param unlockEpoch Epoch number when the funds become withdrawable
    event Unbonded(address indexed sender, bytes32 indexed poolId, uint256 amount, uint256 indexed unlockEpoch);
    /// @notice Emitted when collateral is claimed after unbonding.
    /// @param sender The address that claimed the collateral.
    /// @param poolId The pool id of the validator from which collateral was claimed.
    /// @param amount The amount of collateral claimed.
    event Claimed(address indexed sender, bytes32 indexed poolId, uint256 amount);
    /// @notice Emitted when rewards are claimed for a validator.
    /// @param sender The address that claimed the rewards.
    /// @param poolId The pool id of the validator for which rewards were claimed.
    /// @param amount The amount of rewards claimed.
    event RewardClaimed(address indexed sender, bytes32 indexed poolId, uint256 amount);
    /// @notice Emitted when collateral is transferred back using the Hyperbridge handler.
    /// @param sender The address that initiated the transfer back.
    /// @param amount The amount of collateral transferred back.
    event TransferredBack(address indexed sender, uint256 amount);
    /// @notice Emitted when funds are transferred to the rewards vault.
    /// @param sender The address that initiated the transfer.
    /// @param amount The amount transferred to the rewards vault.
    event TransferredToRewardsVault(address indexed sender, uint256 amount);
    /// @notice Emitted when ETH is deposited to the contract.
    /// @param sender The address that deposited ETH.
    /// @param amount The amount of ETH deposited.
    event EthDeposited(address indexed sender, uint256 amount);
    /// @notice Emitted when the bridge vault address is updated.
    /// @param sender The address that updated the bridge vault.
    /// @param bridgeVault The new bridge vault address.
    event BridgeVaultSet(address indexed sender, address indexed bridgeVault);

    /// @notice Custom errors for amount exceeding limits.
    error AmountExceeds();
    /// @notice Custom errors for insufficient balance.
    error InsufficientBalance();
    /// @notice Custom error for invalid address.
    error InvalidAddress();
    /// @notice Custom error for pool id already registered.
    error PoolIdAlreadyRegistered();
    /// @notice Custom error for pool id not registered.
    error PoolIdNotRegistered();
    /// @notice Custom error for mismatched array lengths in batch operations.
    error MismatchLength();

    constructor() {
        _disableInitializers();
    }

    modifier checkPoolIdExists(bytes32 poolId) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        require($._poolIds.contains(poolId), PoolIdNotRegistered());
        _;
    }

    /// @notice Fallback function to receive ETH deposits.
    receive() external payable {
        emit EthDeposited(msg.sender, msg.value);
    }

    /// @notice Initializes the SlpPharosProxy contract.
    /// @param _initialOwner The initial owner of the contract with DEFAULT_ADMIN_ROLE.
    /// @param _whitelists An array of addresses to be granted the WHITELIST_ROLE.
    /// @param _bridgeVault The address of the bridge vault contract.
    /// @param _rewardsVault The address of the rewards vault contract.
    /// @dev This function can only be called once during the contract's lifetime.
    function initialize(
        address _initialOwner,
        address[] memory _whitelists,
        address _bridgeVault,
        address _rewardsVault
    ) public initializer {
        require(_initialOwner != address(0), InvalidAddress());
        require(_bridgeVault != address(0), InvalidAddress());
        require(_rewardsVault != address(0), InvalidAddress());

        __AccessControlEnumerable_init();
        __ReentrancyGuard_init();

        // Granting the DEFAULT_ADMIN_ROLE
        _grantRole(DEFAULT_ADMIN_ROLE, _initialOwner);
        // Granting the WHITELIST_ROLE
        for (uint256 i = 0; i < _whitelists.length; ++i) {
            require(_whitelists[i] != address(0), InvalidAddress());
            _grantRole(WHITELIST_ROLE, _whitelists[i]);
        }

        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        $._bridgeVault = _bridgeVault;
        $._rewardsVault = _rewardsVault;
    }

    /// @notice Registers a pool id to the whitelist.
    /// @param poolId The pool id to be registered.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function registerPoolId(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        require($._poolIds.add(poolId), PoolIdAlreadyRegistered());

        emit PoolIdRegistered(msg.sender, poolId);
    }

    /// @notice Unregisters a pool id from the whitelist.
    /// @param poolId The pool id to be unregistered.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function unregisterPoolId(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        require($._poolIds.remove(poolId), PoolIdNotRegistered());

        emit PoolIdUnRegistered(msg.sender, poolId);
    }

    /// @notice Bonds a specified amount of collateral to a validator pool.
    /// @param poolId The pool id of the validator to which collateral will be bonded.
    /// @param amount The amount of collateral to bond.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function bond(bytes32 poolId, uint256 amount)
        external
        nonReentrant
        onlyRole(WHITELIST_ROLE)
        checkPoolIdExists(poolId)
    {
        require(amount <= address(this).balance, AmountExceeds());
        STAKING.delegate{value: amount}(poolId);

        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        $._totalBonded += amount;

        emit Bonded(msg.sender, poolId, amount);
    }

    /// @notice Bonds collateral to multiple validator pools in a single transaction.
    /// @param poolIds The pool ids of the validators to which collateral will be bonded.
    /// @param amounts The amount of collateral to bond to each pool, index-aligned with `poolIds`.
    /// @dev Every pool id is validated and the total amount is checked against the contract balance
    ///      before any delegation is made, so the call either bonds to every pool or reverts entirely.
    /// @dev Emits one Bonded event per pool.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function batchBond(bytes32[] calldata poolIds, uint256[] calldata amounts)
        external
        nonReentrant
        onlyRole(WHITELIST_ROLE)
    {
        require(poolIds.length == amounts.length, MismatchLength());

        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        uint256 totalAmount = 0;
        for (uint256 i = 0; i < poolIds.length; ++i) {
            require($._poolIds.contains(poolIds[i]), PoolIdNotRegistered());
            totalAmount += amounts[i];
        }
        require(totalAmount <= address(this).balance, AmountExceeds());

        for (uint256 i = 0; i < poolIds.length; ++i) {
            STAKING.delegate{value: amounts[i]}(poolIds[i]);
            emit Bonded(msg.sender, poolIds[i], amounts[i]);
        }

        $._totalBonded += totalAmount;
    }

    /// @notice Unbonds collateral from a validator pool.
    /// @param poolId The pool id of the validator from which collateral will be unbond
    /// @dev Unbonding will trigger a cooldown period defined by Pharos, after which the collateral can be claimed.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    /// @dev pooId unbond should waiting about 14 days on mainnet before claiming
    function unbond(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) checkPoolIdExists(poolId) {
        (uint256 amount, uint256 unlockEpoch) = STAKING.undelegate(poolId);

        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        $._totalUnbonded += amount;

        emit Unbonded(msg.sender, poolId, amount, unlockEpoch);
    }

    /// @notice Unbonds collateral from multiple validator pools in a single transaction.
    /// @param poolIds The pool ids of the validators from which collateral will be unbonded.
    /// @dev Unbonding will trigger a cooldown period defined by Pharos, after which the collateral can be claimed.
    /// @dev Emits one Unbonded event per pool; the call reverts entirely if any pool id is not registered.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function batchUnbond(bytes32[] calldata poolIds) external nonReentrant onlyRole(WHITELIST_ROLE) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        uint256 totalAmount = 0;

        for (uint256 i = 0; i < poolIds.length; ++i) {
            require($._poolIds.contains(poolIds[i]), PoolIdNotRegistered());
            (uint256 amount, uint256 unlockEpoch) = STAKING.undelegate(poolIds[i]);
            totalAmount += amount;

            emit Unbonded(msg.sender, poolIds[i], amount, unlockEpoch);
        }

        $._totalUnbonded += totalAmount;
    }

    /// @notice Claims collateral after the unbonding cooldown period has passed.
    /// @param poolId The pool id of the validator from which collateral will be claimed.
    /// @dev The collateral can only be claimed after the unlock epoch has been reached.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function claim(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) checkPoolIdExists(poolId) {
        uint256 beforeClaimBalance = address(this).balance;
        STAKING.claimStake(poolId);
        uint256 afterClaimBalance = address(this).balance;
        uint256 claimAmount = afterClaimBalance - beforeClaimBalance;

        emit Claimed(msg.sender, poolId, claimAmount);
    }

    /// @notice Claims collateral from multiple validator pools after their unbonding cooldown periods have passed.
    /// @param poolIds The pool ids of the validators from which collateral will be claimed.
    /// @dev The collateral can only be claimed after each pool's unlock epoch has been reached; the call
    ///      reverts entirely if any pool id is not registered or any single claim fails.
    /// @dev Emits one Claimed event per pool.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function batchClaim(bytes32[] calldata poolIds) external nonReentrant onlyRole(WHITELIST_ROLE) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();

        for (uint256 i = 0; i < poolIds.length; ++i) {
            require($._poolIds.contains(poolIds[i]), PoolIdNotRegistered());
            uint256 beforeClaimBalance = address(this).balance;
            STAKING.claimStake(poolIds[i]);
            uint256 afterClaimBalance = address(this).balance;
            uint256 claimAmount = afterClaimBalance - beforeClaimBalance;

            emit Claimed(msg.sender, poolIds[i], claimAmount);
        }
    }

    /// @notice Claims rewards for a specified validator pool into this contract.
    /// @param poolId The pool id of the validator for which rewards will be claimed.
    /// @dev Pharos does not transfer the reward synchronously: `STAKING.claimReward` only emits `CoinMinted` and the
    ///      node credits the minted amount to this contract after the transaction has executed. The funds are
    ///      therefore NOT available within this transaction; forward them later with `transferToRewardsVault`.
    /// @dev The claimed amount is accumulated in `totalRewardClaimed` for reconciliation.
    /// @dev Reverts (from Pharos) with "No rewards to claim" if the pool has no claimable reward.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function claimReward(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) checkPoolIdExists(poolId) {
        uint256 rewardAmount = STAKING.claimReward(poolId);
        getSlpPharosProxyStorage()._totalRewardClaimed += rewardAmount;

        emit RewardClaimed(msg.sender, poolId, rewardAmount);
    }

    /// @notice Claims rewards from multiple validator pools into this contract in a single transaction.
    /// @param poolIds The pool ids of the validators for which rewards will be claimed.
    /// @dev Same semantics as `claimReward` for each pool: nothing is forwarded to the rewards vault here, use
    ///      `transferToRewardsVault` once Pharos has credited the minted rewards.
    /// @dev Pools whose claimable reward (per `STAKING.getDelegatorReward`) is zero are skipped instead of
    ///      reverting the whole batch, since Pharos' `claimReward` reverts on a zero reward. Skipped pools emit no
    ///      event. The view never over-reports what `claimReward` will settle, so a non-zero check cannot revert;
    ///      it may under-report catch-up rewards of freshly activated stake, which are simply claimed next time.
    /// @dev Emits one RewardClaimed event per claimed pool. The call still reverts entirely if any pool id is not
    ///      registered or a claim fails for another reason.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function batchClaimReward(bytes32[] calldata poolIds) external nonReentrant onlyRole(WHITELIST_ROLE) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        uint256 totalRewardAmount = 0;

        for (uint256 i = 0; i < poolIds.length; ++i) {
            require($._poolIds.contains(poolIds[i]), PoolIdNotRegistered());
            if (STAKING.getDelegatorReward(poolIds[i], address(this)) == 0) {
                continue;
            }
            uint256 rewardAmount = STAKING.claimReward(poolIds[i]);
            totalRewardAmount += rewardAmount;

            emit RewardClaimed(msg.sender, poolIds[i], rewardAmount);
        }

        $._totalRewardClaimed += totalRewardAmount;
    }

    /// @notice Compounds rewards for a specified validator pool.
    /// @param poolId The pool id of the validator for which rewards will be compounded.
    function compoundRewards(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) checkPoolIdExists(poolId) {
        STAKING.compoundRewards(poolId);
    }

    /// @notice Settles rewards for a specified validator pool.
    /// @param poolId The pool id of the validator for which rewards will be settled.
    function settleReward(bytes32 poolId) external nonReentrant onlyRole(WHITELIST_ROLE) checkPoolIdExists(poolId) {
        STAKING.settleReward(poolId);
    }

    /// @notice Settles rewards for multiple validator pools in a single transaction.
    /// @param poolIds The pool ids of the validators for which rewards will be settled.
    /// @dev Only refreshes the staking contract's reward accounting, no funds are moved; the call reverts
    ///      entirely if any pool id is not registered.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    function batchSettleReward(bytes32[] calldata poolIds) external nonReentrant onlyRole(WHITELIST_ROLE) {
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();

        for (uint256 i = 0; i < poolIds.length; ++i) {
            require($._poolIds.contains(poolIds[i]), PoolIdNotRegistered());
            STAKING.settleReward(poolIds[i]);
        }
    }

    /// @notice Transfers a specified amount of collateral back to a given address using the bridge vault.
    /// @param amount The amount of collateral to transfer back.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    /// @dev Emits a TransferredBack event upon successful transfer.
    function transferBack(uint256 amount)
        external
        nonReentrant
        onlyRole(WHITELIST_ROLE)
    {
        require(amount <= address(this).balance, InsufficientBalance());
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        Address.sendValue(payable($._bridgeVault), amount);

        emit TransferredBack(msg.sender, amount);
    }

    /// @notice Transfers a specified amount from the contract balance to the rewards vault.
    /// @param amount The amount to transfer to the rewards vault.
    /// @dev Intended for forwarding rewards previously claimed via `claimReward` / `batchClaimReward`, once Pharos
    ///      has credited the minted amount to this contract (the next block at the latest). The vault reports every
    ///      deposit to the vToken oracle as new rewards, so only reward funds should be sent here; principal goes
    ///      back through `transferBack`.
    /// @dev `totalRewardClaimed() - totalRewardTransferred()` gives the amount still waiting to be forwarded.
    /// @dev Only accounts with the WHITELIST_ROLE can call this function.
    /// @dev Emits a TransferredToRewardsVault event upon successful transfer.
    function transferToRewardsVault(uint256 amount) external nonReentrant onlyRole(WHITELIST_ROLE) {
        require(amount <= address(this).balance, InsufficientBalance());
        SlpPharosProxyStorage storage $ = getSlpPharosProxyStorage();
        $._totalRewardTransferred += amount;
        Address.sendValue(payable($._rewardsVault), amount);

        emit TransferredToRewardsVault(msg.sender, amount);
    }

    /// @notice Updates the bridge vault address used by transferBack.
    /// @param _bridgeVault The new bridge vault address.
    /// @dev Only accounts with the DEFAULT_ADMIN_ROLE can call this function.
    function setBridgeVault(address _bridgeVault) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_bridgeVault != address(0), InvalidAddress());
        getSlpPharosProxyStorage()._bridgeVault = _bridgeVault;

        emit BridgeVaultSet(msg.sender, _bridgeVault);
    }

    /// @notice Checks if a given pool id is registered in the whitelist.
    /// @param poolId The pool id to check.
    /// @return True if the pool id is registered, false otherwise.
    function isPoolIdRegistered(bytes32 poolId) external view returns (bool) {
        return getSlpPharosProxyStorage()._poolIds.contains(poolId);
    }

    /// @notice Returns the list of registered pool ids in the whitelist.
    /// @return An array of registered pool ids.
    function registeredPools() external view returns (bytes32[] memory) {
        return getSlpPharosProxyStorage()._poolIds.values();
    }

    /// @notice Returns the address of the bridge vault contract.
    /// @return The address of the bridge vault contract.
    function getBridgeVault() external view returns (address) {
        return getSlpPharosProxyStorage()._bridgeVault;
    }

    /// @notice Returns the address of the rewards vault contract.
    /// @return The address of the rewards vault contract.
    function getRewardsVault() external view returns (address) {
        return getSlpPharosProxyStorage()._rewardsVault;
    }

    /// @notice Returns the total amount bonded.
    /// @return The total bonded amount.
    function totalBonded() external view returns (uint256) {
        return getSlpPharosProxyStorage()._totalBonded;
    }

    /// @notice Returns the total amount unbonded.
    /// @return The total unbonded amount.
    function totalUnbonded() external view returns (uint256) {
        return getSlpPharosProxyStorage()._totalUnbonded;
    }

    /// @notice Returns the total amount of rewards claimed from Pharos via claimReward / batchClaimReward.
    /// @return The total claimed reward amount.
    function totalRewardClaimed() external view returns (uint256) {
        return getSlpPharosProxyStorage()._totalRewardClaimed;
    }

    /// @notice Returns the total amount transferred to the rewards vault via transferToRewardsVault.
    /// @return The total amount transferred to the rewards vault.
    function totalRewardTransferred() external view returns (uint256) {
        return getSlpPharosProxyStorage()._totalRewardTransferred;
    }
}
